package httpapp

const pageTemplates = `
{{define "page"}}{{template "shell" .}}{{end}}
{{define "shell"}}
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#0f2f43">
  <title>{{.Title}} · NetWeave</title>
  <link rel="stylesheet" href="/assets/app.css">
</head>
<body data-timezone="{{.Timezone}}" data-event-cursor="{{.EventCursor}}">
  <a class="skip-link" href="#main">Skip to main content</a>
  <header class="masthead">
    <div class="brand-lockup">
      <a class="wordmark" href="/dashboard">NET<span>WEAVE</span></a>
      <span class="brand-note">incident net control</span>
    </div>
    {{if .Incident}}
    <div class="masthead-context">
      <span class="context-title">{{.Incident.Title}}</span>
      <span class="state-chip state-{{statusClass (printf "%s" .Incident.Status)}}">{{statusLabel (printf "%s" .Incident.Status)}}</span>
      <span class="context-meta">{{.Incident.Frequency}} · {{.Incident.ControlOperator}}</span>
    </div>
    {{end}}
    <div class="masthead-clock">
      <span class="eyebrow">DATA THROUGH</span>
      <strong>{{dateTime .Now .Timezone}}</strong>
      {{if .Incident}}<span id="live-status" class="live-status" aria-live="polite">SSR snapshot</span>{{end}}
    </div>
  </header>
  {{if .Incident}}
  <nav class="primary-nav" aria-label="Primary navigation">
    <a class="{{if eq .Active "incidents"}}active{{end}}" href="/incidents">Incidents</a>
    <a class="{{if eq .Active "dashboard"}}active{{end}}" href="/incidents/{{.Incident.ID}}">Dashboard</a>
    <a class="{{if eq .Active "traffic"}}active{{end}}" href="/incidents/{{.Incident.ID}}/traffic">Traffic queue</a>
    <a class="{{if eq .Active "stations"}}active{{end}}" href="/incidents/{{.Incident.ID}}/stations">Station board</a>
    <a class="{{if eq .Active "closeout"}}active{{end}}" href="/incidents/{{.Incident.ID}}/closeout">Closeout</a>
    <span class="nav-spacer"></span>
    <a href="/incidents/new">Plan a net</a>
    <a href="/incidents/{{.Incident.ID}}/export.json">Export JSON</a>
    <a href="/incidents/{{.Incident.ID}}/print/traffic">Print log</a>
  </nav>
  {{else}}
  <nav class="primary-nav" aria-label="Primary navigation">
    <a class="{{if eq .Active "dashboard"}}active{{end}}" href="/dashboard">Dashboard</a>
    <a class="{{if eq .Active "incidents"}}active{{end}}" href="/incidents">Incidents</a>
    <span class="nav-spacer"></span>
    <a href="/incidents/new">Plan a net</a>
  </nav>
  {{end}}
  <main id="main" class="workspace">
    {{if .Error}}<div class="alert alert-error" role="alert"><strong>Action not completed.</strong> {{.Error}}</div>{{end}}
    {{template "body" .}}
  </main>
  <footer class="site-footer"><span>NetWeave local operations journal</span><span>Built for calm, accountable handoffs</span></footer>
  {{if .Incident}}
  <script>
  (() => {
    const status = document.getElementById('live-status');
    const endpoint = '/api/incidents/{{.Incident.ID}}/events/stream';
    const cursorKey = 'netweave:event-cursor:{{.Incident.ID}}';
    const timezone = document.body.dataset.timezone || 'UTC';
    let cursor = Math.max(0, Number(document.body.dataset.eventCursor) || 0);
    try { cursor = Math.max(cursor, Number(sessionStorage.getItem(cursorKey)) || 0); } catch (_) {}
    let fallback = null;
    let reloadTimer = null;
    const mark = (value) => { if (status) status.textContent = value; };
    const clock = () => new Date().toLocaleTimeString([], {timeZone: timezone});
    const persistCursor = () => { try { sessionStorage.setItem(cursorKey, String(cursor)); } catch (_) {} };
    const scheduleReload = () => {
      if (reloadTimer) window.clearTimeout(reloadTimer);
      reloadTimer = window.setTimeout(() => window.location.reload(), 260);
    };
    const advance = (next) => {
      if (!Number.isFinite(next) || next <= cursor) return false;
      cursor = next;
      persistCursor();
      scheduleReload();
      return true;
    };
    const poll = async () => {
      try {
        const response = await fetch('/api/incidents/{{.Incident.ID}}/events?since=' + cursor, {headers: {'Accept': 'application/json'}});
        if (!response.ok) throw new Error('poll failed');
        const payload = await response.json();
        let next = cursor;
        for (const event of (payload.data || [])) next = Math.max(next, event.cursor || 0);
        advance(next);
        mark('Polling · ' + clock());
      } catch (_) { mark('Offline · last known'); }
    };
    if (window.EventSource) {
      const source = new EventSource(endpoint + '?since=' + cursor);
      source.onopen = () => { mark('Live · connected'); if (fallback) { clearInterval(fallback); fallback = null; } };
      const receive = (event) => { try { advance(Number(JSON.parse(event.data).cursor || 0)); } catch (_) {} mark('Live · ' + clock()); };
      source.addEventListener('netweave', receive);
      source.onmessage = receive;
      source.onerror = () => { mark('Reconnecting · polling fallback'); if (!fallback) { poll(); fallback = window.setInterval(poll, 8000); } };
    } else { mark('Polling fallback'); poll(); fallback = window.setInterval(poll, 8000); }
  })();
  </script>
  {{end}}
</body>
</html>
{{end}}

{{define "print"}}
<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{.Title}}</title><link rel="stylesheet" href="/assets/app.css"></head>
<body class="print-page">
  <main class="print-sheet">
    <header class="print-header"><div><div class="wordmark">NET<span>WEAVE</span></div><p>Portable incident archive · {{.Incident.Title}}</p></div><dl><dt>Data through</dt><dd>{{dateTime .Now .Timezone}}</dd><dt>Phase</dt><dd>{{statusLabel (printf "%s" .Incident.Status)}}</dd><dt>Frequency</dt><dd>{{.Incident.Frequency}}</dd></dl></header>
    <section class="print-section"><h1>{{.Heading}}</h1><p class="lede">Operational snapshot generated for handoff and after-action review.</p></section>
    <section class="print-section"><h2>Station participation</h2><table class="data-table"><thead><tr><th>Call sign</th><th>Operator</th><th>Location</th><th>Status</th><th>Checked in</th><th>Checked out</th></tr></thead><tbody>{{range .Stations}}<tr><td class="mono">{{.CanonicalCallSign}}</td><td>{{.Operator}}</td><td>{{.Location}}</td><td>{{statusLabel (printf "%s" .Availability)}}</td><td>{{time .CheckedInAt $.Timezone}}</td><td>{{time .CheckedOutAt $.Timezone}}</td></tr>{{end}}</tbody></table></section>
    <section class="print-section"><h2>Traffic register</h2><table class="data-table"><thead><tr><th>#</th><th>Precedence</th><th>From</th><th>To</th><th>Received</th><th>Expiry</th><th>Status</th><th>Disposition</th></tr></thead><tbody>{{range .Actionable}}<tr><td class="mono">{{.Sequence}}</td><td>{{statusLabel .Precedence}}</td><td>{{.Sender}}</td><td>{{.Recipient}}</td><td>{{time .ReceivedAt $.Timezone}}</td><td>{{time .ExpiresAt $.Timezone}}</td><td>{{statusLabel (printf "%s" .Status)}}</td><td>{{.Disposition}}</td></tr>{{end}}{{range .Blocked}}<tr><td class="mono">{{.Sequence}}</td><td>{{statusLabel .Precedence}}</td><td>{{.Sender}}</td><td>{{.Recipient}}</td><td>{{time .ReceivedAt $.Timezone}}</td><td>{{time .ExpiresAt $.Timezone}}</td><td>{{statusLabel (printf "%s" .Status)}}</td><td>{{.Disposition}}</td></tr>{{end}}{{range .Expired}}<tr><td class="mono">{{.Sequence}}</td><td>{{statusLabel .Precedence}}</td><td>{{.Sender}}</td><td>{{.Recipient}}</td><td>{{time .ReceivedAt $.Timezone}}</td><td>{{time .ExpiresAt $.Timezone}}</td><td>{{statusLabel (printf "%s" .Status)}}</td><td>{{.Disposition}}</td></tr>{{end}}</tbody></table></section>
    <section class="print-section"><h2>Closeout totals</h2><div class="metric-strip"><div><span>Stations</span><strong>{{.Summary.StationCount}}</strong></div><div><span>Traffic</span><strong>{{.Summary.TrafficCount}}</strong></div><div><span>Delivered</span><strong>{{.Summary.DeliveredCount}}</strong></div><div><span>Unresolved</span><strong>{{.Summary.UnresolvedCount}}</strong></div><div><span>Relay attempts</span><strong>{{.Summary.RelayAttempts}}</strong></div></div></section>
  </main>
</body>
</html>
{{end}}

{{define "body"}}
{{if eq .View "empty"}}
  <section class="empty-state"><p class="eyebrow">NO ACTIVE INCIDENT</p><h1>Plan the next net.</h1><p>Set the operating window, staff the station board, and keep formal traffic accountable from first receipt to final disposition.</p><a class="button button-primary" href="/incidents/new">Plan a new incident</a></section>
{{else if eq .View "dashboard"}}
  <section class="page-intro"><div><p class="eyebrow">CURRENT OPERATIONS</p><h1>{{.Heading}}</h1><p class="lede">One place for net control, station availability, and formal traffic handoffs.</p></div><div class="intro-actions">{{if eq .Incident.Status "planned"}}<form method="post" action="/incidents/{{.Incident.ID}}/lifecycle"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="status" value="open"><button class="button button-primary" type="submit">Open incident</button></form>{{else if or (eq .Incident.Status "open") (eq .Incident.Status "reopened")}}<a class="button button-primary" href="/incidents/{{.Incident.ID}}/traffic/new">Capture traffic</a><a class="button button-quiet" href="/incidents/{{.Incident.ID}}/stations">Check stations</a>{{else}}<a class="button button-primary" href="/incidents/{{.Incident.ID}}/closeout">Review closeout</a>{{end}}</div></section>
  <section class="metric-strip" aria-label="Incident status"><div><span>Net phase</span><strong>{{statusLabel (printf "%s" .Incident.Status)}}</strong><small>{{time .Incident.OpenedAt .Timezone}}</small></div><div><span>Checked in</span><strong>{{.Summary.StationCount}}</strong><small>{{.Summary.CheckedOutCount}} checked out</small></div><div><span>Actionable</span><strong>{{len .Actionable}}</strong><small>{{len .Blocked}} blocked</small></div><div><span>Unresolved</span><strong>{{.Summary.UnresolvedCount}}</strong><small>{{.Summary.DeliveredCount}} delivered</small></div><div><span>Journal events</span><strong>{{.Summary.AuditEntries}}</strong><small>audited transitions</small></div></section>
  <div class="content-grid">
    <section class="panel panel-priority"><div class="panel-heading"><div><p class="eyebrow">NEEDS ACTION</p><h2>Dispatch queue</h2></div><a class="text-link" href="/incidents/{{.Incident.ID}}/traffic">Open full queue</a></div>{{if .Actionable}}<div class="queue-list">{{range .Actionable}}<a class="queue-row" href="/incidents/{{$.Incident.ID}}/traffic/{{.ID}}"><span class="priority priority-{{.Precedence}}">{{statusLabel .Precedence}}</span><span class="queue-number">#{{.Sequence}}</span><span class="queue-route"><strong>{{.Sender}}</strong><span>to</span><strong>{{.Recipient}}</strong></span><span class="queue-age">{{age .ReceivedAt $.Now}}</span><span class="queue-arrow">View</span></a>{{end}}</div>{{else}}<p class="empty-inline">No immediately actionable traffic. The queue is clear.</p>{{end}}</section>
    <section class="panel"><div class="panel-heading"><div><p class="eyebrow">STATION BOARD</p><h2>Who is on air</h2></div><a class="text-link" href="/incidents/{{.Incident.ID}}/stations">Manage</a></div><div class="station-mini-list">{{range .Stations}}<div class="station-mini"><span class="status-dot dot-{{statusClass (printf "%s" .Availability)}}"></span><span class="mono">{{.CanonicalCallSign}}</span><span>{{.Operator}}</span><span class="muted">{{statusLabel (printf "%s" .Availability)}}</span></div>{{else}}<p class="empty-inline">No stations checked in yet.</p>{{end}}</div></section>
  </div>
  <section class="panel panel-timeline"><div class="panel-heading"><div><p class="eyebrow">AUDIT TRAIL</p><h2>Recent transitions</h2></div><span class="muted">Append-only journal</span></div><ol class="timeline">{{range $index, $entry := .Incident.Audit}}{{if ge $index 0}}{{if lt $index 8}}<li><span class="timeline-time">{{time $entry.At $.Timezone}}</span><span class="timeline-mark"></span><span><strong>{{$entry.Kind}}</strong><small>{{$entry.Details}} · {{$entry.Actor}}</small></span></li>{{end}}{{end}}{{else}}<li class="empty-inline">No transitions recorded.</li>{{end}}</ol></section>
{{else if eq .View "stations"}}
  <section class="page-intro"><div><p class="eyebrow">LIVE STATION BOARD</p><h1>{{.Heading}}</h1><p class="lede">Canonical call signs preserve each check-in session and prevent ambiguous handoffs.</p></div><div class="intro-actions"><a class="button button-quiet" href="/incidents/{{.Incident.ID}}/print/stations">Print board</a></div></section>
  <section class="panel form-panel"><div class="panel-heading"><div><p class="eyebrow">CHECK IN</p><h2>Add an operating station</h2></div><span class="muted">Active call signs must be unique</span></div><form method="post" action="/incidents/{{.Incident.ID}}/stations/check-in" class="form-grid"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><label>Call sign<input name="call_sign" value="{{value .Form "call_sign"}}" placeholder="K1ABC" autocomplete="off"><small>{{fieldError .Errors "call_sign"}}</small></label><label>Operator<input name="operator" value="{{value .Form "operator"}}" placeholder="Name or role"><small>{{fieldError .Errors "operator"}}</small></label><label>Location<input name="location" value="{{value .Form "location"}}" placeholder="North sector / home QTH"></label><label>Bands<input name="bands" value="{{value .Form "bands"}}" placeholder="2m, 70cm"></label><label>Modes<input name="modes" value="{{value .Form "modes"}}" placeholder="FM, Winlink"></label><label>Equipment<input name="equipment" value="{{value .Form "equipment"}}" placeholder="HT, mobile, gateway"></label><label class="field-wide">Notes<textarea name="notes" rows="2">{{value .Form "notes"}}</textarea></label><div class="field-wide form-actions"><button class="button button-primary" type="submit">Check in station</button></div></form></section>
  <section class="panel"><div class="panel-heading"><div><p class="eyebrow">PARTICIPATION</p><h2>{{len .Stations}} station sessions</h2></div><span class="muted">Status changes are audited</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Call sign</th><th>Operator</th><th>Location</th><th>Capability</th><th>Status</th><th>Checked in</th><th>Update</th></tr></thead><tbody>{{range .Stations}}<tr><td class="mono strong">{{.CanonicalCallSign}}<small>{{.RawCallSign}}</small></td><td>{{.Operator}}</td><td>{{.Location}}</td><td><span class="mono">{{join .Bands ", "}}</span><small>{{join .Modes ", "}}</small></td><td><span class="status-tag status-{{statusClass (printf "%s" .Availability)}}">{{statusLabel (printf "%s" .Availability)}}</span></td><td class="mono">{{time .CheckedInAt $.Timezone}}</td><td><form method="post" action="/incidents/{{$.Incident.ID}}/stations/{{.ID}}/availability" class="inline-form"><input type="hidden" name="csrf_token" value="{{$.CSRF}}"><input type="hidden" name="expected_version" value="{{.Version}}"><select name="availability" aria-label="Set availability for {{.CanonicalCallSign}}"><option value="available">Available</option><option value="temporarily-away">Temporarily away</option><option value="checked-out">Checked out</option></select><button class="button button-small" type="submit">Update</button></form></td></tr>{{else}}<tr><td colspan="7" class="empty-inline">No stations checked in.</td></tr>{{end}}</tbody></table></div></section>
{{else if eq .View "traffic"}}
  <section class="page-intro"><div><p class="eyebrow">FORMAL TRAFFIC</p><h1>{{.Heading}}</h1><p class="lede">Priority, expiry, received time, and incident sequence keep dispatch deterministic.</p></div><div class="intro-actions"><a class="button button-primary" href="/incidents/{{.Incident.ID}}/traffic/new">Capture traffic</a><a class="button button-quiet" href="/incidents/{{.Incident.ID}}/print/traffic">Print log</a></div></section>
  <section class="panel panel-priority"><div class="panel-heading"><div><p class="eyebrow">ACTIONABLE</p><h2>Ready for claim <span class="count-badge">{{len .Actionable}}</span></h2></div><span class="muted">Oldest and highest precedence first</span></div><div class="table-wrap"><table class="data-table traffic-table"><thead><tr><th>Pri</th><th>Traffic</th><th>Route</th><th>Age</th><th>Expiry</th><th>State</th><th></th></tr></thead><tbody>{{range .Actionable}}<tr><td><span class="priority priority-{{.Precedence}}">{{statusLabel .Precedence}}</span></td><td class="mono strong">#{{.Sequence}}<small>{{.ID}}</small></td><td><strong>{{.Sender}}</strong><span class="route-arrow">→</span><strong>{{.Recipient}}</strong></td><td class="mono">{{age .ReceivedAt $.Now}}</td><td class="mono">{{time .ExpiresAt $.Timezone}}</td><td><span class="status-tag status-queued">QUEUED</span></td><td><a class="button button-small" href="/incidents/{{$.Incident.ID}}/traffic/{{.ID}}">Open</a></td></tr>{{else}}<tr><td colspan="7" class="empty-inline">The actionable queue is clear.</td></tr>{{end}}</tbody></table></div></section>
  <div class="content-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">BLOCKED</p><h2>Needs a state change</h2></div></div><div class="compact-list">{{range .Blocked}}<a href="/incidents/{{$.Incident.ID}}/traffic/{{.ID}}"><span class="mono">#{{.Sequence}}</span><span>{{.Sender}} → {{.Recipient}}</span><span class="muted">{{statusLabel (printf "%s" .Status)}}</span></a>{{else}}<p class="empty-inline">No blocked traffic.</p>{{end}}</div></section><section class="panel panel-warning"><div class="panel-heading"><div><p class="eyebrow">EXPIRY WATCH</p><h2>Expired or at boundary</h2></div></div><div class="compact-list">{{range .Expired}}<a href="/incidents/{{$.Incident.ID}}/traffic/{{.ID}}"><span class="mono">#{{.Sequence}}</span><span>{{.Sender}} → {{.Recipient}}</span><span class="muted">{{time .ExpiresAt $.Timezone}}</span></a>{{else}}<p class="empty-inline">No expired traffic.</p>{{end}}</div></section></div>
{{else if eq .View "detail"}}
  <section class="page-intro"><div><p class="eyebrow">TRAFFIC #{{.Traffic.Sequence}}</p><h1>{{.Traffic.Sender}} <span class="route-arrow">→</span> {{.Traffic.Recipient}}</h1><p class="lede">Received {{dateTime .Traffic.ReceivedAt .Timezone}} · expires {{dateTime .Traffic.ExpiresAt .Timezone}}</p></div><div class="detail-status"><span class="priority priority-{{.Traffic.Precedence}}">{{statusLabel .Traffic.Precedence}}</span><span class="status-tag status-{{statusClass (printf "%s" .Traffic.Status)}}">{{statusLabel (printf "%s" .Traffic.Status)}}</span></div></section>
  <div class="detail-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">MESSAGE BODY</p><h2>Formal traffic</h2></div><span class="mono">v{{.Traffic.RecordVersion}}</span></div><dl class="detail-list"><dt>Sender</dt><dd>{{.Traffic.Sender}}</dd><dt>Recipient</dt><dd>{{.Traffic.Recipient}}</dd><dt>Handling instructions</dt><dd>{{if .Traffic.HandlingInstructions}}{{.Traffic.HandlingInstructions}}{{else}}None recorded{{end}}</dd><dt>Idempotency key</dt><dd class="mono">{{.Traffic.IdempotencyKey}}</dd></dl><pre class="traffic-body">{{.Traffic.Body}}</pre></section><aside class="action-rail"><section class="panel"><p class="eyebrow">NEXT ACTION</p>{{if eq .Traffic.Status "queued"}}<form method="post" action="/incidents/{{.Incident.ID}}/traffic/{{.Traffic.ID}}/claim"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="expected_version" value="{{.Traffic.RecordVersion}}"><label>Assign to<select name="station_id" required><option value="">Choose a station</option>{{range .Stations}}{{if eq (printf "%s" .Availability) "available"}}<option value="{{.ID}}">{{.CanonicalCallSign}} · {{.Operator}}</option>{{end}}{{end}}</select></label><button class="button button-primary button-block" type="submit">Claim traffic</button></form>{{else if eq .Traffic.Status "assigned"}}<form method="post" action="/incidents/{{.Incident.ID}}/traffic/{{.Traffic.ID}}/start"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="expected_version" value="{{.Traffic.RecordVersion}}"><button class="button button-primary button-block" type="submit">Start relay</button></form><form method="post" action="/incidents/{{.Incident.ID}}/traffic/{{.Traffic.ID}}/release"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="expected_version" value="{{.Traffic.RecordVersion}}"><button class="button button-quiet button-block" type="submit">Return to queue</button></form>{{else if eq .Traffic.Status "in-flight"}}<form method="post" action="/incidents/{{.Incident.ID}}/traffic/{{.Traffic.ID}}/ack"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="expected_version" value="{{.Traffic.RecordVersion}}"><label>Acknowledgement key<input name="acknowledgement_key" value="{{value .Form "acknowledgement_key"}}" required placeholder="destination-ack-01"><small>{{fieldError .Errors "acknowledgement_key"}}</small></label><label>Outcome<select name="final"><option value="true" {{if eq (value .Form "final") "true"}}selected{{end}}>Final delivery</option><option value="false" {{if eq (value .Form "final") "false"}}selected{{end}}>Relay leg complete</option></select></label><label>Reason<input name="reason" value="{{value .Form "reason"}}" placeholder="Read-back confirmed"></label><button class="button button-primary button-block" type="submit">Record acknowledgement</button></form><form method="post" action="/incidents/{{.Incident.ID}}/traffic/{{.Traffic.ID}}/fail-attempt"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="expected_version" value="{{.Traffic.RecordVersion}}"><label>Attempt failure reason<input name="reason" value="{{value .Form "reason"}}" required placeholder="No response or path unavailable"><small>{{fieldError .Errors "reason"}}</small></label><button class="button button-quiet button-block" type="submit">Record failed attempt</button></form>{{else}}<p class="muted">This traffic is terminal. Preserve the record in the archive.</p>{{end}}<div class="action-divider"></div><form method="post" action="/incidents/{{.Incident.ID}}/traffic/{{.Traffic.ID}}/disposition"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><label>Closeout disposition<input name="disposition" value="{{if (value .Form "disposition")}}{{value .Form "disposition"}}{{else}}{{.Traffic.Disposition}}{{end}}" placeholder="Deferred to next net"></label><button class="button button-quiet button-block" type="submit">Save disposition</button></form></section></aside></div>
  <section class="panel panel-timeline"><div class="panel-heading"><div><p class="eyebrow">IMMUTABLE HISTORY</p><h2>Relay timeline</h2></div><span class="muted">Every state change remains reviewable</span></div><ol class="timeline">{{range .Traffic.History}}<li><span class="timeline-time">{{time .At $.Timezone}}</span><span class="timeline-mark"></span><span><strong>{{statusLabel (printf "%s" .From)}} → {{statusLabel (printf "%s" .To)}}</strong><small>{{.Reason}} · {{.Actor}}</small></span></li>{{end}}</ol>{{if .Traffic.RelayAttempts}}<div class="relay-register"><h3>Relay attempts</h3>{{range .Traffic.RelayAttempts}}<div class="relay-row"><span class="mono">LEG {{.Number}}</span><span>{{.StationID}}</span><span>{{.Destination}}</span><span class="muted">{{if .Outcome}}{{statusLabel .Outcome}}{{else}}In progress{{end}}</span></div>{{end}}</div>{{end}}</section>
{{else if eq .View "closeout"}}
  <section class="page-intro"><div><p class="eyebrow">END OF NET</p><h1>{{.Heading}}</h1><p class="lede">Resolve open work, capture the handoff, and close with a complete audit trail.</p></div><div class="intro-actions"><a class="button button-quiet" href="/incidents/{{.Incident.ID}}/print/closeout">Print closeout</a></div></section>
  <section class="metric-strip"><div><span>Stations</span><strong>{{.Summary.StationCount}}</strong><small>{{.Summary.CheckedOutCount}} checked out</small></div><div><span>Traffic</span><strong>{{.Summary.TrafficCount}}</strong><small>{{.Summary.DeliveredCount}} delivered</small></div><div><span>Unresolved</span><strong>{{.Summary.UnresolvedCount}}</strong><small>must have a disposition</small></div><div><span>Relay attempts</span><strong>{{.Summary.RelayAttempts}}</strong><small>ordered legs</small></div></section>
  <div class="content-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">RECONCILIATION</p><h2>Open traffic</h2></div><span class="muted">Each item needs a disposition</span></div><div class="closeout-list">{{range .Incident.Traffic}}{{if or (eq .Status "queued") (eq .Status "assigned") (eq .Status "in-flight")}}<div class="closeout-row"><div><strong class="mono">#{{.Sequence}}</strong><span>{{.Sender}} → {{.Recipient}}</span><span class="status-tag status-{{statusClass (printf "%s" .Status)}}">{{statusLabel (printf "%s" .Status)}}</span></div><form method="post" action="/incidents/{{$.Incident.ID}}/traffic/{{.ID}}/disposition"><input type="hidden" name="csrf_token" value="{{$.CSRF}}"><label class="sr-only" for="disposition-{{.ID}}">Disposition for traffic #{{.Sequence}}</label><input id="disposition-{{.ID}}" name="disposition" value="{{.Disposition}}" placeholder="Deferred, transferred, or resolved"><button class="button button-small" type="submit">Save</button></form></div>{{end}}{{end}}{{if eq .Summary.UnresolvedCount 0}}<p class="empty-inline">All traffic has a terminal outcome.</p>{{end}}</div></section><section class="panel panel-close"><div class="panel-heading"><div><p class="eyebrow">FINAL CONTROL</p><h2>Close this incident</h2></div></div><p>Closing writes an audited transition and freezes normal mutations. Unresolved traffic must have explicit dispositions first.</p>{{if eq .Incident.Status "closing"}}<form method="post" action="/incidents/{{.Incident.ID}}/closeout"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><button class="button button-primary button-block" type="submit">Confirm closeout</button></form>{{else if eq .Incident.Status "closed"}}<p class="status-note">Closed {{dateTime .Incident.ClosedAt .Timezone}}. Authorized follow-up may reopen the net.</p><form method="post" action="/incidents/{{.Incident.ID}}/lifecycle"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="status" value="reopened"><label>Audited reason<input name="reason" required placeholder="Follow-up traffic or correction"></label><button class="button button-primary button-block" type="submit">Reopen incident</button></form>{{else if eq .Incident.Status "planned"}}<form method="post" action="/incidents/{{.Incident.ID}}/lifecycle"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="status" value="open"><button class="button button-primary button-block" type="submit">Open incident</button></form>{{else}}<form method="post" action="/incidents/{{.Incident.ID}}/lifecycle"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="status" value="closing"><button class="button button-primary button-block" type="submit">Move to closing</button></form>{{end}}</section></div>
{{else if eq .View "incidents"}}
  <section class="page-intro"><div><p class="eyebrow">INCIDENT REGISTER</p><h1>{{.Heading}}</h1><p class="lede">Open current operations or return to prior incident records.</p></div><div class="intro-actions"><a class="button button-primary" href="/incidents/new">Plan a net</a></div></section>
  <section class="panel"><div class="panel-heading"><div><p class="eyebrow">ALL NETS</p><h2>{{len .Incidents}} incidents</h2></div><span class="muted">Newest first</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Incident</th><th>Phase</th><th>Frequency</th><th>Control</th><th>Created</th><th></th></tr></thead><tbody>{{range .Incidents}}<tr><td><strong>{{.Title}}</strong><small class="mono">{{.ID}}</small></td><td><span class="status-tag status-{{statusClass (printf "%s" .Status)}}">{{statusLabel (printf "%s" .Status)}}</span></td><td>{{.Frequency}}</td><td>{{.ControlOperator}}</td><td class="mono">{{time .CreatedAt .Timezone}}</td><td><a class="button button-small" href="/incidents/{{.ID}}">Open</a></td></tr>{{else}}<tr><td colspan="6" class="empty-inline">No incidents have been planned.</td></tr>{{end}}</tbody></table></div></section>
{{else if eq .View "new-incident"}}
  <section class="form-page"><p class="eyebrow">PLAN A NET</p><h1>{{.Heading}}</h1><p class="lede">Give control a clear operating frame before stations check in.</p><form method="post" action="/incidents/new" class="panel form-grid"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><label class="field-wide">Incident title<input name="title" value="{{value .Form "title"}}" placeholder="County storm drill · evening net" autofocus><small>{{fieldError .Errors "title"}}</small></label><label>Operational timezone<input name="timezone" value="{{value .Form "timezone"}}" placeholder="America/Los_Angeles"><small>{{fieldError .Errors "timezone"}}</small></label><label>Net frequency<input name="frequency" value="{{value .Form "frequency"}}" placeholder="146.520 MHz"><small>{{fieldError .Errors "frequency"}}</small></label><label class="field-wide">Control operator<input name="control_operator" value="{{value .Form "control_operator"}}" placeholder="Call sign or name"><small>{{fieldError .Errors "control_operator"}}</small></label><div class="field-wide form-actions"><button class="button button-primary" type="submit">Create planned incident</button><a class="button button-quiet" href="/dashboard">Cancel</a></div></form></section>
{{else if eq .View "new-traffic"}}
  <section class="form-page"><p class="eyebrow">{{.Incident.Title}}</p><h1>{{.Heading}}</h1><p class="lede">Capture the original values once. Validation errors keep the submitted form intact for correction.</p><form method="post" action="/incidents/{{.Incident.ID}}/traffic/new" class="panel form-grid"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><label>Sender<input name="sender" value="{{value .Form "sender"}}" placeholder="Originating station"><small>{{fieldError .Errors "sender"}}</small></label><label>Recipient<input name="recipient" value="{{value .Form "recipient"}}" placeholder="Destination station"><small>{{fieldError .Errors "recipient"}}</small></label><label>Precedence<select name="precedence"><option value="routine" {{if eq (value .Form "precedence") "routine"}}selected{{end}}>Routine</option><option value="priority" {{if eq (value .Form "precedence") "priority"}}selected{{end}}>Priority</option><option value="immediate" {{if eq (value .Form "precedence") "immediate"}}selected{{end}}>Immediate</option><option value="flash" {{if eq (value .Form "precedence") "flash"}}selected{{end}}>Flash</option></select><small>{{fieldError .Errors "precedence"}}</small></label><label>Received at<input type="{{if fieldError .Errors "received_at"}}text{{else}}datetime-local{{end}}" name="received_at" value="{{value .Form "received_at"}}"><small>{{fieldError .Errors "received_at"}}</small></label><label>Expires at<input type="{{if fieldError .Errors "expires_at"}}text{{else}}datetime-local{{end}}" name="expires_at" value="{{value .Form "expires_at"}}" required><small>{{fieldError .Errors "expires_at"}}</small></label><label>Idempotency key<input class="mono" name="idempotency_key" value="{{value .Form "idempotency_key"}}" required><small>{{fieldError .Errors "idempotency_key"}}</small></label><label class="field-wide">Message body<textarea name="body" rows="9" required>{{value .Form "body"}}</textarea><small>{{fieldError .Errors "body"}}</small></label><label class="field-wide">Handling instructions<textarea name="handling_instructions" rows="3">{{value .Form "handling_instructions"}}</textarea></label><div class="field-wide form-actions"><button class="button button-primary" type="submit">Queue formal traffic</button><a class="button button-quiet" href="/incidents/{{.Incident.ID}}/traffic">Cancel</a></div></form></section>
{{else}}
  <section class="empty-state"><p class="eyebrow">REQUEST STATUS</p><h1>{{.Heading}}</h1><p>{{.Error}}</p><a class="button button-primary" href="/dashboard">Return to dashboard</a></section>
{{end}}
{{end}}
`

const appCSS = `
:root { --ink:#10212b; --muted:#52636d; --line:#d8e0e4; --paper:#f5f7f7; --surface:#ffffff; --navy:#0f2f43; --blue:#03698f; --blue-dark:#034e69; --amber:#9a5b00; --amber-bg:#fff7e8; --red:#a33d38; --red-bg:#fff0ef; --green:#236b52; --green-bg:#edf8f1; --radius:4px; --sans:"Fira Sans", "Avenir Next", "Segoe UI", sans-serif; --mono:"Fira Code", "SFMono-Regular", Consolas, monospace; }
* { box-sizing:border-box; } html { background:var(--paper); color:var(--ink); font-family:var(--sans); } body { margin:0; min-width:320px; font-size:15px; line-height:1.5; } a { color:var(--blue-dark); } a:hover { color:var(--blue); } button, input, textarea, select { font:inherit; } button, .button, select { cursor:pointer; } .skip-link { position:absolute; left:12px; top:-60px; background:var(--navy); color:#fff; padding:8px 12px; z-index:20; } .skip-link:focus { top:12px; }
.masthead { min-height:88px; background:var(--navy); color:#f6fbfd; display:flex; align-items:center; gap:32px; padding:18px clamp(18px,4vw,56px); border-bottom:4px solid #eea53b; } .brand-lockup { display:flex; align-items:baseline; gap:12px; min-width:235px; } .wordmark { color:#fff; text-decoration:none; font-weight:700; font-size:19px; letter-spacing:.08em; } .wordmark span { color:#f1b14c; } .brand-note, .context-meta, .eyebrow, .masthead-clock .eyebrow { text-transform:uppercase; letter-spacing:.1em; font-size:10px; } .brand-note { color:#a9c1cc; } .masthead-context { display:flex; align-items:center; gap:12px; min-width:0; flex:1; } .context-title { font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } .context-meta { color:#a9c1cc; } .masthead-clock { display:grid; gap:1px; text-align:right; min-width:165px; } .masthead-clock strong { font-family:var(--mono); font-size:12px; font-weight:500; } .live-status { color:#a9d6c0; font-size:11px; }
.primary-nav { min-height:48px; padding:0 clamp(18px,4vw,56px); display:flex; align-items:center; gap:4px; background:#fff; border-bottom:1px solid var(--line); } .primary-nav a { min-height:48px; display:flex; align-items:center; padding:0 14px; text-decoration:none; color:var(--muted); font-size:13px; border-bottom:3px solid transparent; } .primary-nav a:hover, .primary-nav a.active { color:var(--navy); border-bottom-color:#eea53b; } .nav-spacer { flex:1; }
.workspace { width:min(1440px, 100%); margin:0 auto; padding:32px clamp(18px,4vw,56px) 56px; } .page-intro { display:flex; justify-content:space-between; gap:32px; align-items:flex-end; margin-bottom:28px; } h1, h2, h3, p { margin-top:0; } h1 { margin-bottom:8px; color:var(--navy); font-size:clamp(28px,4vw,44px); line-height:1.08; letter-spacing:0; } h2 { margin-bottom:0; color:var(--navy); font-size:20px; line-height:1.2; } h3 { font-size:15px; } .lede { max-width:650px; color:var(--muted); font-size:16px; margin-bottom:0; } .eyebrow { color:var(--blue); font-weight:700; margin-bottom:8px; } .muted { color:var(--muted); font-size:12px; } .mono { font-family:var(--mono); font-size:12px; } .strong { font-weight:700; }
.intro-actions { display:flex; gap:8px; flex-wrap:wrap; justify-content:flex-end; } .button { min-height:40px; display:inline-flex; align-items:center; justify-content:center; gap:6px; padding:8px 14px; border:1px solid transparent; border-radius:var(--radius); text-decoration:none; font-weight:600; font-size:13px; transition:background-color .18s ease, border-color .18s ease, color .18s ease; } .button-primary { background:var(--blue); color:#fff; } .button-primary:hover { background:var(--blue-dark); color:#fff; } .button-quiet { background:#fff; border-color:var(--line); color:var(--navy); } .button-quiet:hover { border-color:var(--blue); color:var(--blue-dark); } .button-small { min-height:32px; padding:5px 9px; font-size:12px; background:#fff; border:1px solid var(--line); border-radius:var(--radius); color:var(--navy); } .button-small:hover { border-color:var(--blue); } .button-block { width:100%; } button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible { outline:3px solid #f0b348; outline-offset:2px; }
.metric-strip { display:grid; grid-template-columns:repeat(5,1fr); border:1px solid var(--line); background:var(--surface); margin-bottom:20px; } .metric-strip > div { padding:16px 18px; border-right:1px solid var(--line); min-width:0; } .metric-strip > div:last-child { border-right:0; } .metric-strip span, .metric-strip small { display:block; color:var(--muted); font-size:11px; } .metric-strip strong { display:block; color:var(--navy); font-family:var(--mono); font-size:22px; margin:2px 0; } .content-grid, .detail-grid { display:grid; grid-template-columns:minmax(0,1.55fr) minmax(300px,1fr); gap:20px; margin-bottom:20px; } .detail-grid { grid-template-columns:minmax(0,1.6fr) minmax(280px,.7fr); } .panel { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); margin-bottom:20px; } .content-grid > .panel, .detail-grid > .panel, .detail-grid > aside > .panel { margin-bottom:0; } .panel-heading { display:flex; align-items:flex-start; justify-content:space-between; gap:20px; padding:18px 20px; border-bottom:1px solid var(--line); } .panel-heading .eyebrow { margin-bottom:4px; } .text-link { white-space:nowrap; font-size:12px; font-weight:700; } .panel-priority { border-top:3px solid #eea53b; } .panel-warning { border-top:3px solid #d78931; } .panel-close { border-top:3px solid var(--blue); } .panel-timeline { padding-bottom:8px; } .form-panel { padding-bottom:4px; }
.queue-list, .station-mini-list, .compact-list, .closeout-list { padding:4px 20px 10px; } .queue-row { display:grid; grid-template-columns:80px 55px minmax(0,1fr) 50px 42px; gap:12px; align-items:center; min-height:54px; border-bottom:1px solid #edf1f2; text-decoration:none; color:var(--ink); } .queue-row:last-child { border-bottom:0; } .queue-row:hover { background:#f7fbfc; margin:0 -20px; padding-left:20px; padding-right:20px; } .priority { display:inline-flex; align-items:center; min-height:23px; padding:2px 7px; border:1px solid currentColor; border-radius:3px; font-size:10px; letter-spacing:.07em; font-weight:700; text-transform:uppercase; white-space:nowrap; } .priority-routine { color:#52636d; } .priority-priority { color:#176a8b; background:#eff8fb; } .priority-immediate { color:#9a5b00; background:var(--amber-bg); } .priority-flash { color:#a33d38; background:var(--red-bg); } .queue-number { font-family:var(--mono); font-size:12px; font-weight:600; } .queue-route { display:flex; gap:7px; align-items:center; min-width:0; } .queue-route span, .route-arrow { color:var(--muted); font-size:12px; } .queue-route strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; } .queue-age { font-family:var(--mono); font-size:11px; color:var(--muted); text-align:right; } .queue-arrow { color:var(--blue); font-size:11px; font-weight:700; text-align:right; } .count-badge { display:inline-block; margin-left:5px; padding:2px 7px; background:#eef5f7; color:var(--blue-dark); border-radius:10px; font-family:var(--mono); font-size:11px; vertical-align:middle; } .empty-inline { color:var(--muted); padding:16px 0; margin:0; font-size:13px; }
.station-mini { display:grid; grid-template-columns:12px 70px minmax(0,1fr) auto; gap:9px; align-items:center; min-height:43px; border-bottom:1px solid #edf1f2; } .station-mini:last-child { border-bottom:0; } .station-mini .mono { font-weight:700; } .status-dot { width:8px; height:8px; border-radius:50%; background:#9aaab1; } .dot-available { background:#3d9975; } .dot-assigned { background:#e0a13a; } .dot-temporarily_away { background:#d78931; } .dot-checked_out { background:#9aaab1; } .status-chip, .status-tag { display:inline-flex; align-items:center; width:max-content; padding:3px 7px; border-radius:3px; font-size:10px; font-weight:700; letter-spacing:.06em; } .status-chip { color:#f7fbfd; background:#2d708b; } .status-tag { color:var(--muted); border:1px solid var(--line); } .status-available, .status-delivered { color:var(--green); background:var(--green-bg); border-color:#b8dfca; } .status-assigned, .status-in_flight, .status-closing { color:var(--amber); background:var(--amber-bg); border-color:#f0d7a9; } .status-queued, .status-planned, .status-reopened { color:var(--blue-dark); background:#eef7fa; border-color:#bfdde8; } .status-failed, .status-expired, .status-cancelled, .status-checked_out, .status-temporarily_away { color:var(--red); background:var(--red-bg); border-color:#ecc6c3; }
.timeline { list-style:none; margin:0; padding:13px 20px 0; } .timeline li { display:grid; grid-template-columns:100px 18px minmax(0,1fr); gap:10px; min-height:52px; position:relative; } .timeline li:not(:last-child)::after { content:""; position:absolute; left:108px; top:21px; bottom:0; width:1px; background:var(--line); } .timeline-time { font-family:var(--mono); font-size:11px; color:var(--muted); padding-top:1px; } .timeline-mark { width:9px; height:9px; border:2px solid var(--blue); background:#fff; border-radius:50%; margin-top:3px; z-index:1; } .timeline strong, .timeline small { display:block; } .timeline strong { font-size:13px; } .timeline small { color:var(--muted); font-size:12px; margin-top:2px; }
.table-wrap { overflow-x:auto; } .data-table { width:100%; border-collapse:collapse; font-size:13px; } .data-table th { text-align:left; color:var(--muted); font-size:10px; letter-spacing:.08em; text-transform:uppercase; font-weight:700; padding:11px 14px; background:#f7f9f9; border-bottom:1px solid var(--line); white-space:nowrap; } .data-table td { padding:13px 14px; border-bottom:1px solid #edf1f2; vertical-align:middle; } .data-table tr:last-child td { border-bottom:0; } .data-table td small, .data-table td strong { display:block; } .data-table td small { color:var(--muted); font-size:11px; margin-top:2px; } .traffic-table td:nth-child(3) { white-space:nowrap; } .traffic-table .route-arrow { padding:0 6px; }
.form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; padding:22px 20px; } .form-grid label, .action-rail label { display:grid; gap:6px; color:var(--navy); font-size:12px; font-weight:700; } .form-grid input, .form-grid textarea, .form-grid select, .action-rail input, .action-rail textarea, .action-rail select, .closeout-row input { width:100%; min-height:40px; padding:8px 10px; color:var(--ink); background:#fff; border:1px solid #cbd6da; border-radius:var(--radius); } textarea { resize:vertical; } .form-grid small { color:var(--red); font-size:11px; min-height:14px; font-weight:400; } .field-wide { grid-column:1 / -1; } .form-actions { display:flex; gap:8px; align-items:center; padding-top:4px; } .inline-form { display:flex; gap:5px; align-items:center; min-width:250px; } .inline-form select { min-height:32px; padding:4px 7px; font-size:12px; } .action-rail .panel { padding-bottom:16px; } .action-rail .panel > p, .action-rail form { margin:18px 18px 0; } .action-rail form + form { margin-top:8px; } .action-divider { border-top:1px solid var(--line); margin:18px 0; }
.detail-list { display:grid; grid-template-columns:150px minmax(0,1fr); margin:0; padding:18px 20px 0; gap:8px 16px; } .detail-list dt { color:var(--muted); font-size:12px; } .detail-list dd { margin:0; font-size:13px; } .traffic-body { white-space:pre-wrap; overflow:auto; margin:18px 20px 20px; padding:16px; background:#f7f9f9; border:1px solid var(--line); font:13px/1.6 var(--mono); } .relay-register { margin:8px 20px 20px; border-top:1px solid var(--line); padding-top:12px; } .relay-row { display:grid; grid-template-columns:70px 1fr 1fr 130px; gap:10px; padding:9px 0; border-bottom:1px solid #edf1f2; font-size:12px; }
.closeout-row { display:grid; grid-template-columns:minmax(0,1fr) minmax(240px,.7fr); align-items:center; gap:16px; padding:12px 0; border-bottom:1px solid #edf1f2; } .closeout-row > div { display:flex; gap:10px; align-items:center; flex-wrap:wrap; } .closeout-row form { display:flex; gap:6px; } .closeout-row input { min-height:34px; font-size:12px; } .status-note { padding:12px; border:1px solid #b8dfca; background:var(--green-bg); color:var(--green); font-size:13px; }
.alert { border:1px solid; padding:12px 16px; margin-bottom:20px; border-radius:var(--radius); font-size:13px; } .alert-error { color:var(--red); background:var(--red-bg); border-color:#ecc6c3; } .empty-state, .form-page { max-width:720px; margin:9vh auto; } .empty-state { padding:42px clamp(22px,5vw,64px); background:#fff; border-left:4px solid #eea53b; border-top:1px solid var(--line); border-right:1px solid var(--line); border-bottom:1px solid var(--line); } .empty-state h1, .form-page h1 { margin-bottom:12px; } .empty-state p:not(.eyebrow) { color:var(--muted); max-width:560px; margin-bottom:24px; } .form-page .panel { margin-top:25px; } .site-footer { display:flex; justify-content:space-between; padding:18px clamp(18px,4vw,56px); border-top:1px solid var(--line); color:var(--muted); font-size:11px; }
.print-page { background:#fff; } .print-sheet { max-width:1200px; margin:0 auto; padding:32px; } .print-header { display:flex; justify-content:space-between; gap:32px; border-bottom:2px solid var(--navy); padding-bottom:18px; } .print-header p { color:var(--muted); margin:6px 0 0; } .print-header dl { display:grid; grid-template-columns:auto auto; gap:4px 18px; margin:0; font-size:12px; } .print-header dt { color:var(--muted); } .print-header dd { margin:0; font-family:var(--mono); } .print-section { margin-top:28px; } .print-section h1 { font-size:28px; } .print-section h2 { border-bottom:1px solid var(--line); padding-bottom:8px; margin-bottom:0; } .print-section .metric-strip { border:0; } .print-section .metric-strip > div { padding-left:0; } .sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0; }
@media (max-width:900px) { .masthead { flex-wrap:wrap; gap:10px 20px; } .masthead-context { order:3; flex-basis:100%; } .masthead-clock { margin-left:auto; } .content-grid, .detail-grid { grid-template-columns:1fr; } .metric-strip { grid-template-columns:repeat(3,1fr); } .metric-strip > div:nth-child(3) { border-right:0; } .metric-strip > div:nth-child(n+4) { border-top:1px solid var(--line); } .metric-strip > div:nth-child(4) { border-right:1px solid var(--line); } }
@media (max-width:620px) { body { font-size:14px; } .brand-note, .context-meta { display:none; } .masthead { min-height:72px; padding:14px 16px; } .masthead-clock { min-width:0; } .primary-nav { overflow-x:auto; padding:0 12px; } .primary-nav a { padding:0 10px; white-space:nowrap; } .workspace { padding:24px 14px 40px; } .page-intro { display:block; margin-bottom:22px; } .intro-actions { justify-content:flex-start; margin-top:16px; } h1 { font-size:31px; } .metric-strip { grid-template-columns:repeat(2,1fr); } .metric-strip > div { border-right:1px solid var(--line) !important; } .metric-strip > div:nth-child(2n) { border-right:0 !important; } .metric-strip > div:nth-child(n+3) { border-top:1px solid var(--line); } .queue-row { grid-template-columns:70px 45px minmax(0,1fr) 38px; gap:7px; } .queue-age { display:none; } .queue-arrow { font-size:0; } .queue-arrow::after { content:"Open"; font-size:11px; } .panel-heading { padding:15px; } .queue-list, .station-mini-list, .compact-list, .closeout-list { padding-left:15px; padding-right:15px; } .form-grid { grid-template-columns:1fr; padding:18px 15px; } .field-wide { grid-column:auto; } .form-actions { flex-wrap:wrap; } .detail-list { grid-template-columns:1fr; gap:2px; } .detail-list dt { margin-top:8px; } .relay-row { grid-template-columns:60px 1fr; } .relay-row span:nth-child(3), .relay-row span:nth-child(4) { grid-column:2; } .closeout-row { grid-template-columns:1fr; } .closeout-row form { width:100%; } .inline-form { min-width:0; flex-wrap:wrap; } .site-footer { display:block; } .site-footer span { display:block; margin:3px 0; } .print-sheet { padding:16px; } .print-header { display:block; } .print-header dl { margin-top:16px; } }
@media print { .print-page { font-size:11px; } .print-sheet { padding:0; } .print-header { break-inside:avoid; } .print-section { break-inside:avoid; } .data-table thead { display:table-header-group; } .data-table tr { break-inside:avoid; } }
`
